// Function returns character count (int r)
// Compiler warns if r is unused.

int count;
const char *err_msg = "File not found";

// Suppress warning using the conditional operator:
// The return value r is used in the (r >= 0) condition.
(printf("ERROR: %s\n", err_msg) >= 0) ? (void)0 : (void)0;

// Shorter form if the result type is simple (int)
count = 1 + 2;
(count > 0) ? (printf("C:%d\n", count)) : (void)0;
